using System.Numerics;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;

namespace MinMax;

public static class RangeCalculator
{
    /// <summary>
    /// Returns the minimum and maximum values in <paramref name="values"/>.
    /// Uses SIMD vectorization for high throughput on large spans.
    /// </summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static (float Min, float Max) FindMinMax(ReadOnlySpan<float> values)
    {
        if (values.Length == 0)
            throw new ArgumentException("Span must not be empty.");

        if (!Vector.IsHardwareAccelerated || values.Length < Vector<float>.Count * 2)
            return FindMinMaxScalar(values);

        return FindMinMaxVectorized(values);
    }

    private static (float Min, float Max) FindMinMaxVectorized(ReadOnlySpan<float> values)
    {
        int vectorSize = Vector<float>.Count;
        ReadOnlySpan<Vector<float>> vectors = MemoryMarshal.Cast<float, Vector<float>>(values);
        int vectorCount = vectors.Length;

        var vMin = vectors[0];
        var vMax = vectors[0];

        // Process two vectors per iteration to improve instruction-level parallelism
        int i = 1;
        int unrolledEnd = vectorCount - 1;
        for (; i < unrolledEnd; i += 2)
        {
            var v0 = vectors[i];
            var v1 = vectors[i + 1];
            vMin = Vector.Min(vMin, Vector.Min(v0, v1));
            vMax = Vector.Max(vMax, Vector.Max(v0, v1));
        }

        for (; i < vectorCount; i++)
        {
            vMin = Vector.Min(vMin, vectors[i]);
            vMax = Vector.Max(vMax, vectors[i]);
        }

        // Reduce vectors to scalar min/max
        float min = vMin[0];
        float max = vMax[0];
        for (int j = 1; j < vectorSize; j++)
        {
            if (vMin[j] < min) min = vMin[j];
            if (vMax[j] > max) max = vMax[j];
        }

        // Handle remaining elements not covered by full vectors
        int processed = vectorCount * vectorSize;
        for (int j = processed; j < values.Length; j++)
        {
            if (values[j] < min) min = values[j];
            if (values[j] > max) max = values[j];
        }

        return (min, max);
    }

    private static (float Min, float Max) FindMinMaxScalar(ReadOnlySpan<float> values)
    {
        float min = values[0];
        float max = values[0];
        for (int i = 1; i < values.Length; i++)
        {
            if (values[i] < min) min = values[i];
            if (values[i] > max) max = values[i];
        }
        return (min, max);
    }
}

